import{z as l,x as s,o as t,c as d,q as n,j as B,D as a,d as r,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"GMM","description":"","frontmatter":{"title":"GMM","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gmm-econ.md","filePath":"econ/gmm-econ.md","lastUpdated":1791413859000}'),m={name:"econ/gmm-econ.md"};function h(p,E,D,M,C,g){const A=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=n('<h1 id="gmm" tabindex="-1">GMM <a class="header-anchor" href="#gmm" aria-label="Permalink to &quot;GMM&quot;">​</a></h1><div class="epigraph"><p>矩条件 $\\mathbb{E}[g(W,\\theta)]=0$ 把 IV、Euler 方程和过度识别检验写成同一套加权距离；最优权重是样本矩的协方差之逆，不是把识别变成自动的。</p><footer>—— Hansen, Large Sample Properties of Generalized Method of Moments Estimators, Econometrica 1982；对照 Theil 的 2SLS；Wooldridge 的 GMM 章节</footer></div><p><a href="/econ/2sls-overid">上一课</a>在线性 IV 里写出 2SLS 与 Hansen–Sargan \\(J\\)。本课不重推第一阶段投影，也不把弱工具诊断再列一遍。缺口是：同一套矩语言如何容纳非线性、异方差最优权重，以及「\\(J\\) 不拒绝」在一般 GMM 里仍然只是工具彼此一致。后课<a href="/econ/difference-in-differences">双重差分</a>换识别设计，不再堆矩；本课把 2SLS 收进母框架，并分清一步与两步。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>总体 \\(\\mathbb{E}[g(W_i,\\theta_0)]=0\\)，\\(g\\) 为 \\(L\\times 1\\)，\\(\\theta\\) 为 \\(k\\times 1\\)，\\(L\\ge k\\)。样本矩 \\(\\bar g(\\theta)\\)。恰好识别：\\(L=k\\)，解 \\(\\bar g(\\hat\\theta)=0\\)，IV 的 Wald 比是特例。过度识别：方程多于未知数，一般无精确零点，最小化 \\(\\bar g(\\theta)&#39;W\\bar g(\\theta)\\)。缺口是 \\(W\\) 怎么选、非线性 \\(g\\) 时 2SLS 公式不再够用。消费 Euler、生产函数矩、动态面板差分矩，都是「不是 \\(Z&#39;(Y-X\\beta)\\)」的 \\(g\\)。</p><p><span class="marginnote">术语翻译：「矩条件」就是对模型提的一个要求，形如「某个平均数应当等于零」——比如「工具和残差不相关」，或「今天消费的边际效用满足欧拉方程」。挑一个参数，让这些样本平均数尽量接近零，就是广义矩估计。名字唬人，内核是「对平均数」。</span></p><p>若各矩对应不同的局部效应，最优 GMM 仍会交出一个加权点；\\(J\\) 拒绝可以是异质，不一定是「矩全错」——这与上一课 LATE 混权是同一警告，只是现在不限于线性 IV。</p><h3 id="有效-gmm-不是识别已证实" tabindex="-1">有效 GMM 不是识别已证实 <a class="header-anchor" href="#有效-gmm-不是识别已证实" aria-label="Permalink to &quot;有效 GMM 不是识别已证实&quot;">​</a></h3><p>两步最优 \\(W\\) 给出的是：矩正确时的渐近效率。矩错误时，它有效地估错参数。\\(J\\) 有自由度只因为过度识别；恰好识别时 \\(J\\) 恒为零，排除约束仍不可检验。不要把「用了 GMM」写成论文的识别段落。</p><p><span class="marginnote">直觉类比：恰好识别像用两颗钉子固定一根直尺——钉子总能对上，没法验错；过度识别像用三颗钉子钉一根直尺，三颗能同时严丝合缝，才给「直尺是直的」（矩设定可信）多添一层证据。钉子越多（\\(L-k\\) 越大），检验越有力。</span></p><p><span class="marginnote">同方差线性 IV 下，2SLS 即最优 GMM。异方差时，最优权重换成 \\(\\mathrm{Var}(Z_i u_i)\\) 之逆，点估计可以不同于 2SLS。软件里「IV GMM」与 2SLS 不必相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一步：预先固定 \\(W\\)（常用 \\(I\\) 或 \\(Z&#39;Z\\) 类）。两步：用第一步 \\(\\hat\\theta\\) 估 \\(\\widehat{\\mathrm{Var}}(\\bar g)\\)，再代入最优 \\(W\\)。连续更新 GMM 把两步迭代到不动点，小样本有时更稳。过度识别统计量 \\(J=n\\bar g(\\hat\\theta)&#39;\\widehat{V}^{-1}\\bar g(\\hat\\theta)\\xrightarrow{d}\\chi^2_{L-k}\\)，与上一课 \\(J\\) 同一逻辑。聚类或 HAC 出现在 \\(V\\) 的估计里：上一课与<a href="/econ/clustered-se">聚类</a>的协方差，在此变成矩的协方差。</p>',13)),(t(),B(i,null,{default:a(()=>[o(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TSLS%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%202SLS%20%E4%B8%8E%20J%22%5D%20--%3E%20MOM%5B%22%E4%B8%80%E8%88%AC%E7%9F%A9%20E%20g(W%2C%CE%B8)%3D0%22%5D%0A%20%20MOM%20--%3E%20W%5B%22%E5%8A%A0%E6%9D%83%E6%9C%80%E5%B0%8F%E5%8C%96%20g%CC%84'%20W%20g%CC%84%22%5D%0A%20%20W%20--%3E%20OPT%5B%22%E4%B8%A4%E6%AD%A5%3A%20W%20%E5%8F%96%20Var(g%CC%84)%20%E4%B9%8B%E9%80%86%22%5D%0A%20%20MOM%20--%3E%20NL%5B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%3A%20Euler%E3%80%81%E7%94%9F%E4%BA%A7%E5%87%BD%E6%95%B0%22%5D%0A%20%20OPT%20--%3E%20J%5B%22%E8%BF%87%E5%BA%A6%E8%AF%86%E5%88%AB%20J%22%5D%0A%20%20J%20--%3E%20DID%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%8D%A2%E6%88%90%E6%97%B6%E9%97%B4%E4%B8%8A%E7%9A%84%E6%94%BF%E7%AD%96%E5%B7%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"弱矩与弱 IV 同源：第一阶段弱，GMM 有限样本偏向差、名义 \\(J\\) 水平也会坏。先强度，再谈最优权重。Arellano–Bond 是差分矩上的 GMM，装置留给动态面板课，本课只指出它不是另一套哲学。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是把「正交条件」变成可计算的距离。\\(W\\) 最优时，估计量在这组矩的半参数类里达到效率界。直觉：相关更强、噪声更小的矩，应得到更大权重。非线性时没有封闭的两阶段投影，牛顿法在 \\(\\bar g\\) 上找加权零点——识别靠的仍是总体矩为真，不是优化器收敛。",-1)),(t(),B(i,null,{default:a(()=>[o(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E9%80%89%E5%AE%9A%E7%9F%A9%E6%9D%A1%E4%BB%B6%20g%20%E4%B8%8E%E5%B7%A5%E5%85%B7%20Z%22%5D%20--%3E%20ONE%5B%22%E7%AC%AC%E4%B8%80%E6%AD%A5%EF%BC%9A%E7%94%A8%E7%AE%80%E5%8D%95%E6%9D%83%E9%87%8D%20W%3DI%20%E6%9C%80%E5%B0%8F%E5%8C%96%EF%BC%8C%E5%BE%97%20%CE%B8%E2%82%81%22%5D%0A%20%20ONE%20--%3E%20VHAT%5B%22%E7%94%A8%E6%AE%8B%E5%B7%AE%E4%BC%B0%E8%AE%A1%E7%9F%A9%E7%9A%84%E5%8D%8F%E6%96%B9%E5%B7%AE%20V%20%3D%20Var(%E1%B8%A1)%22%5D%0A%20%20VHAT%20--%3E%20WINV%5B%22%E6%9C%80%E4%BC%98%E6%9D%83%E9%87%8D%20W%20%E5%8F%96%20V%20%E4%B9%8B%E9%80%86%EF%BC%9A%E5%99%AA%E5%A3%B0%E5%B0%8F%E7%9A%84%E7%9F%A9%E6%9D%83%E9%87%8D%E5%A4%A7%22%5D%0A%20%20WINV%20--%3E%20TWO%5B%22%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E9%87%8D%E6%96%B0%E6%9C%80%E5%B0%8F%E5%8C%96%20%E1%B8%A1'W%E1%B8%A1%EF%BC%8C%E5%BE%97%20%CE%B8%E2%82%82%22%5D%0A%20%20TWO%20--%3E%20JTEST%5B%22%E7%AE%97%20J%20%E7%BB%9F%E8%AE%A1%E9%87%8F%EF%BC%8C%E5%AF%B9%E7%85%A7%20%CF%87%C2%B2(L%E2%88%92k)%22%5D%0A%20%20JTEST%20--%3E%20OK%5B%22%E4%B8%8D%E6%8B%92%E7%BB%9D%EF%BC%9A%E7%9F%A9%E5%BD%BC%E6%AD%A4%E4%B8%80%E8%87%B4%EF%BC%8C%E4%BD%86%E4%B8%8D%E7%AD%89%E4%BA%8E%E8%AF%86%E5%88%AB%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20JTEST%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E6%9F%90%E6%9D%A1%E7%9F%A9%E5%8F%AF%E8%83%BD%E9%94%99%E4%BA%86%EF%BC%8C%E5%9B%9E%E6%9F%A5%E8%AE%BE%E5%AE%9A%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">数字实例：两个矩各给出一个估计，2.0（标准误 0.5）与 2.4（标准误 2.0）。最优权重按方差倒数分配，前者的权重是后者的 \\(2.0^2/0.5^2=16\\) 倍，加权估计被拉向 2.0。「更准的矩说话声音更大」就是 \\(W\\) 取方差之逆的全部含义。</span></p><p>Hansen 把 Sargan 的过度识别从同方差 IV 推到一般异方差。因此本课不是 2SLS 的重复：它回答「若 \\(g\\) 不是 \\(Zu\\)，权重与 \\(J\\) 从哪来」。</p><p><span class="marginnote">小样本里第二步的 \\(\\widehat{V}\\) 很吵，两步 GMM 可以比一步更散。许多应用报告一步、两步和 Hansen \\(J\\) 一起，避免只展示最漂亮的那一列。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 Hansen 的全部渐近定理，也不把三阶段、控制函数菜单写完。不把 GMM 当成因果识别的替代品：矩来自排除、Euler 或模型，对错仍要领域约束。量化栏资产定价的 Hansen–Jagannathan 与 SDF 矩是另一条应用，本课不搬过去，以免金融微观结构吞并。下一课起，识别更多来自处理组与对照组在时间上的差，而不是再加一个 \\(Z\\)。</p><p>后课默认：线性 IV 先 2SLS / LIML；需要非线性或异方差最优权重时升到 GMM，并解释 \\(J\\)（排除失败对异质）。不要用 \\(J\\) 的 \\(p\\) 值替代恰好识别时不可检验的那条排除。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GMM 用 \\(\\mathbb{E}[g]=0\\) 统一线性 IV 与非线性矩。</li><li>2SLS 是同方差 IV 下的最优 GMM 特例。</li><li>两步 \\(W\\) 管效率，不管矩是否为真。</li><li>\\(J\\) 检验过度约束彼此是否一致，不证实单条排除。</li><li>出处：Hansen, <em>Econometrica</em> 1982；Theil 2SLS；Wooldridge；Angrist and Pischke。</li></ul>',8))])}const F=l(m,[["render",h]]);export{c as __pageData,F as default};
